class Solution {
    int cross(const vector<int>& o, const vector<int>& a, const vector<int>& b) {
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
    }
public:
    vector<vector<int>> outerTrees(vector<vector<int>>& trees) {
        sort(trees.begin(), trees.end());
        vector<vector<int>> lower;
        for (const auto& p : trees) {
            while (lower.size() >= 2 && cross(lower[lower.size() - 2], lower.back(), p) < 0) {
                lower.pop_back();
            }
            lower.push_back(p);
        }

        vector<vector<int>> upper;
        for (int i = (int)trees.size() - 1; i >= 0; i--) {
            const auto& p = trees[i];
            while (upper.size() >= 2 && cross(upper[upper.size() - 2], upper.back(), p) < 0) {
                upper.pop_back();
            }
            upper.push_back(p);
        }

        set<vector<int>> unique(lower.begin(), lower.end());
        unique.insert(upper.begin(), upper.end());
        return vector<vector<int>>(unique.begin(), unique.end());
    }
};

class Solution {
    private int cross(int[] o, int[] a, int[] b) {
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
    }

    public int[][] outerTrees(int[][] trees) {
        Arrays.sort(trees, (a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
        List<int[]> lower = new ArrayList<>();
        for (int[] p : trees) {
            while (lower.size() >= 2 && cross(lower.get(lower.size() - 2), lower.get(lower.size() - 1), p) < 0) {
                lower.remove(lower.size() - 1);
            }
            lower.add(p);
        }

        List<int[]> upper = new ArrayList<>();
        for (int i = trees.length - 1; i >= 0; i--) {
            int[] p = trees[i];
            while (upper.size() >= 2 && cross(upper.get(upper.size() - 2), upper.get(upper.size() - 1), p) < 0) {
                upper.remove(upper.size() - 1);
            }
            upper.add(p);
        }

        Set<String> seen = new HashSet<>();
        List<int[]> res = new ArrayList<>();
        for (int[] p : lower) {
            if (seen.add(p[0] + "," + p[1])) res.add(p);
        }
        for (int[] p : upper) {
            if (seen.add(p[0] + "," + p[1])) res.add(p);
        }
        return res.toArray(new int[res.size()][]);
    }
}

var outerTrees = function(trees) {
    trees.sort((a, b) => a[0] !== b[0] ? a[0] - b[0] : a[1] - b[1]);

    function cross(o, a, b) {
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
    }

    const lower = [];
    for (const p of trees) {
        while (lower.length >= 2 && cross(lower[lower.length - 2], lower[lower.length - 1], p) < 0) {
            lower.pop();
        }
        lower.push(p);
    }

    const upper = [];
    for (let i = trees.length - 1; i >= 0; i--) {
        const p = trees[i];
        while (upper.length >= 2 && cross(upper[upper.length - 2], upper[upper.length - 1], p) < 0) {
            upper.pop();
        }
        upper.push(p);
    }

    const seen = new Set();
    const res = [];
    for (const p of [...lower, ...upper]) {
        const key = `${p[0]},${p[1]}`;
        if (!seen.has(key)) {
            seen.add(key);
            res.push(p);
        }
    }
    return res;
};
